{
    "$schema": "http://json-schema.org/draft-07/schema#",
    "$id": "https://mcda.drugis.org/valueCIEffect.json#",
    "title": "MCDA value, confidence interval effect for the performance table entry of absolute data",
    "type": "object",
    "required": [
        "type",
        "value",
        "input"
    ],
    "additionalProperties": false,
    "properties": {
        "type": {
            "type": "string",
            "enum": [
                "exact"
            ]
        },
        "value": {
            "type": "number"
        },
        "input": {
            "type": "object",
            "required": [
                "value",
                "lowerBound",
                "upperBound"
            ],
            "additionalProperties": false,
            "properties": {
                "value": {
                    "type": "number"
                },
                "lowerBound": {
                    "oneOf": [
                        {
                            "type": "number"
                        },
                        {
                            "type": "string",
                            "enum": [
                                "NE"
                            ]
                        }
                    ]
                },
                "upperBound": {
                    "oneOf": [
                        {
                            "type": "number"
                        },
                        {
                            "type": "string",
                            "enum": [
                                "NE"
                            ]
                        }
                    ]
                },
                "scale": {
                    "type": "string",
                    "enum": [
                        "percentage",
                        "decimal"
                    ]
                }
            }
        }
    }
}

